def _delegate_to_references_loop(self, templar):
    if self._task.loop is None and self._task.loop_with is None:
        return False

    delegate_to = self._task.delegate_to
    if not isinstance(delegate_to, string_types) or not templar.is_template(delegate_to):
        return False

    loop_control = self._task.loop_control
    loop_vars = {'ansible_loop', 'ansible_loop_var', loop_control.loop_var or 'item'}
    if loop_control.index_var:
        loop_vars.add(loop_control.index_var)

    try:
        referenced_vars = meta.find_undeclared_variables(templar.environment.parse(delegate_to))
    except TemplateSyntaxError:
        # Let normal templating report malformed templates with its own error.
        return False
    return bool(loop_vars.intersection(referenced_vars))

def _resolve_delegation(self, variables, templar=None):
    if templar is None:
        templar = Templar(loader=self._loader, variables=variables)
    delegated_vars, delegated_host_name = self._variable_manager.get_delegated_vars_and_hostname(templar, self._task, variables)
    if delegated_host_name is not None:
        variables.setdefault('ansible_delegated_vars', {}).update(delegated_vars)
        self._task.delegate_to = delegated_host_name

